<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, rows, keyOf, pretty, type Row } from './api'
import JsonView from './JsonView.vue'
const error = ref(''), busy = ref(false), tab = ref('jobs'), items = ref<Row[]>([]), detail = ref<any>(null), editor = ref(''), editorOpen = ref(false), editorTitle = ref(''), path = ref(''), method = ref('POST'), traceId = ref('')
const endpoints: Record<string, string> = { jobs: '/admin/jobs', configs: '/admin/configs', budget: '/admin/budget', feedback: '/admin/feedback', users: '/admin/users', groups: '/admin/groups' }
async function act(fn: () => Promise<void>) { busy.value = true; error.value = ''; try { await fn() } catch (e) { error.value = String(e) } finally { busy.value = false } }
async function load() { items.value = rows(await api(endpoints[tab.value])) }
function edit(title: string, endpoint: string, body: unknown, verb = 'POST') { editorTitle.value = title; path.value = endpoint; method.value = verb; editor.value = pretty(body); editorOpen.value = true }
async function save() { await act(async () => { detail.value = await api(path.value, method.value, JSON.parse(editor.value)); editorOpen.value = false; await load() }) }
onMounted(() => act(load))
</script>
<template><section><h2>运行与维护</h2><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-tabs v-model="tab" @tab-change="act(load)"><el-tab-pane label="后台任务" name="jobs" /><el-tab-pane label="策略配置" name="configs" /><el-tab-pane label="模型预算" name="budget" /><el-tab-pane label="用户反馈" name="feedback" /><el-tab-pane label="用户" name="users" /><el-tab-pane label="用户组" name="groups" /></el-tabs><div class="toolbar"><el-button :loading="busy" @click="act(load)">刷新</el-button><el-button v-if="tab === 'configs'" @click="edit('新建不可变配置版本', '/admin/configs', {kind: 'RETRIEVAL', name: '', payload: {query: {rewrite:false, hyde:false, multiQuery:false, maxVariants:4}, retrieval: {mode:'BM25', perRouteK:50, numCandidates:200, representations:['ORIGINAL']}, fusion: {rrfK:60}, post: {parent:false, mmr:false, lambda:0.7, rerank:false}, context: {maxTokens:6000, maxUnits:6}}})">新建配置</el-button></div><el-table :data="items" empty-text="没有记录"><el-table-column label="名称 / ID" min-width="240"><template #default="{row}">{{ row.name || row.loginName || row.question || keyOf(row) }}</template></el-table-column><el-table-column prop="status" label="状态" /><el-table-column prop="stage" label="阶段" /><el-table-column prop="errorCode" label="错误" /><el-table-column label="操作" min-width="250"><template #default="{row}"><el-button size="small" @click="act(async () => { detail = tab === 'jobs' ? await api('/admin/jobs/' + keyOf(row)) : row })">详情</el-button><template v-if="tab === 'jobs'"><el-button size="small" @click="act(async () => { detail = await api('/admin/jobs/' + keyOf(row) + '/retry', 'POST'); await load() })">重试</el-button><el-button size="small" @click="act(async () => { detail = await api('/admin/jobs/' + keyOf(row) + '/cancel', 'POST'); await load() })">取消</el-button></template><el-button v-if="tab === 'configs'" size="small" @click="act(async () => { detail = await api('/admin/configs/' + keyOf(row) + '/publish', 'POST'); await load() })">设为默认</el-button><el-button v-if="tab === 'feedback'" size="small" @click="edit('处理反馈', '/admin/feedback/' + keyOf(row), {status:'IN_PROGRESS', resolution:''}, 'PATCH')">处理</el-button><el-button v-if="tab === 'groups'" size="small" @click="edit('组成员替换', '/admin/groups/' + keyOf(row) + '/members', {userIds:row.userIds || [], expectedSecurityEpoch:row.securityEpoch}, 'PUT')">成员</el-button></template></el-table-column></el-table><el-collapse><el-collapse-item title="运行 Trace"><div class="toolbar"><el-input v-model="traceId" placeholder="运行 ID" /><el-button :disabled="!traceId" @click="act(async () => { detail = await api('/admin/runs/' + traceId + '/trace') })">读取受控 Trace</el-button></div></el-collapse-item></el-collapse><JsonView v-if="detail" :value="detail" /><el-dialog v-model="editorOpen" :title="editorTitle" width="800px"><el-input v-model="editor" type="textarea" :rows="16" aria-label="维护 JSON" /><template #footer><el-button type="primary" :loading="busy" @click="save">提交</el-button></template></el-dialog></section></template>
